// Tier check (stub) -- RELEASE-TIERS.md structural hook (added 2026-06-03).
//
// PLACEHOLDER. This node is wired pass-through and does NOT yet enforce
// release tiers. It reserves the structural slot where tier-detection logic
// plugs in on a follow-up commit. The actual classification logic is the
// wf36 follow-up build; this commit only establishes the hook so future
// commits know where to plug in.
//
// Upcoming logic (per docs/00-foundations/_root/RELEASE-TIERS.md):
//   1. Read the candidate-change metadata from the POST body
//      (surface_type, metadata.commit_hash, metadata.author, files touched).
//   2. Run the ~10-second decision flowchart from RELEASE-TIERS.md to classify
//      the change as Tier A / Tier B / Tier C:
//        - Tier C if it touches money flow, a new module/API, front-door /
//          About / mission identity, sponsor-alignment criteria, Family Voice
//          Loop integrity, a COLG-facing surface, or first onboarding of a new
//          family / community.
//        - Tier B if user-trust-bearing otherwise (new feature, visual change,
//          workflow refactor, tier / pricing copy).
//        - Tier A if it passes all six low-risk tests
//          (feedback-risk-clarify-before-change) or is a security / documented
//          bug-fix / copy / memory / NAS-only change.
//   3. Attach { release_tier, tier_reason } to the item so the four-test gate
//      and the response can enforce Tier C = requires Quality Gatekeeper
//      sign-off, while Tier A / B pass straight through.
//   4. Honor the override clause: a reviewer 'tier-down' / 'tier-up' wins and
//      is logged with the decision.
//
// Until that logic lands, this node passes every item through untouched so the
// existing four-test gate behavior is unchanged.

return $input.all();

// Quality Gatekeeper (wf36) -- deploy-time POLICY GATE. Role 10 per
// PERPETUAL-PIPELINE-HEALTH.md / AI-TEAM-DISTRIBUTION.
//
// Encodes the FOUR ETHICAL TESTS from BODY-OF-CHRIST-ECONOMIC-STEWARDSHIP.md
// plus the Grace and Mercy Standard (docs/00-foundations/01-grace-and-mercy-standard.md)
// as deterministic Code-node checks. Returns PASS / WARN / BLOCK with the
// cited test, plain-language reasoning, and a Scripture anchor (ESV primary).
// Logs every decision to /data/chatin/_telemetry/qg/<safeTs>__gate.json and
// appends a one-line event to _events.jsonl for the dust-off-feet tally.
//
// The four tests:
//   1. Deuteronomy 8:18 -- Yahweh is the SOURCE of the power to get wealth;
//      wealth is covenantal lift, never a faith-formula yield. (Catches the
//      prosperity-gospel inversion -- BODY-OF-CHRIST Section 11 bright line.)
//   2. John 10:10 -- abundant life, not the thief. The surface gives life
//      (empowers, serves, hands back understanding) and never operates like
//      the thief who steals/kills/destroys (extraction, surveillance, dark UX,
//      lock-in). (DATA-AS-EMPOWERMENT-NOT-EXTRACTION.)
//   3. James 1:27 -- pure-and-undefiled religion: CARE for the afflicted AND
//      keep UNSTAINED from the world. Catches both abandonment of the
//      vulnerable and world-stained counterfeits (e.g. a race-exclusive
//      "church" that breaks the multi-racial Body -- Gal 3:28 / Col 3:11).
//   4. Grace and Mercy Standard -- never gatekeep on theological precision,
//      never declare users outside fellowship over secondary issues, never
//      withdraw grace based on behavior. (Romans 5:8.)
//
// Advisory, not absolute: Darrell + Christina + Bishop Gwin may override a
// BLOCK by logging the override (see QUALITY-GATEKEEPER.md). Section O
// engagement strategy: a surface that hits BLOCK repeatedly earns a
// dust-off-feet escalation to human governance (Matthew 10:14).
//
// Typographic theology per CLAUDE.md: the capitalized adversary names in the
// violation-detection regex below are MATCH TARGETS -- content that honors the
// adversary FAILS the gate. They are never honorific uses.
//
// POST body shape:
//   { surface_type, content_snapshot,
//     metadata: { commit_hash, author, sovereign_mesh_tier, surface_id } }

const fs = require('fs');
const path = require('path');

const input = $input.first().json || {};
const body = (input.body && typeof input.body === 'object') ? input.body : input;

const surfaceType = (body.surface_type || 'unspecified').toString();
const content = (body.content_snapshot == null)
  ? ''
  : (typeof body.content_snapshot === 'string' ? body.content_snapshot : JSON.stringify(body.content_snapshot));
const metadata = (body.metadata && typeof body.metadata === 'object') ? body.metadata : {};
const commitHash = (metadata.commit_hash || metadata.commitHash || '').toString();
const author = (metadata.author || '').toString();
const sovereignMeshTier = (metadata.sovereign_mesh_tier || metadata.sovereignMeshTier || '').toString();
const surfaceId = (metadata.surface_id || metadata.surfaceId || surfaceType).toString();

if (!content) {
  return [{ json: { ok: false, error: 'content_snapshot is required', decision: 'WARN' } }];
}

// Match helper: patterns carry no /g flag so .test is stateless and reusable.
function anyMatch(text, patterns) {
  const hits = [];
  for (let i = 0; i < patterns.length; i++) {
    if (patterns[i].re.test(text)) hits.push(patterns[i].label);
  }
  return hits;
}

// ---- Test 1: Deuteronomy 8:18 -- Yahweh-source, not a wealth formula.
const T1_BLOCK = [
  { re: /sow (a |your )?(seed|\$|\d)/i, label: 'seed-faith sowing-for-return language' },
  { re: /seed[\s-]?faith/i, label: 'seed-faith framing' },
  { re: /name it and claim it/i, label: '"name it and claim it" formula' },
  { re: /hundredfold (return|blessing|harvest)/i, label: 'guaranteed-hundredfold-return claim' },
  { re: /guarantee[ds]? (you )?(wealth|riches|financial|a return|money|prosperity)/i, label: 'guaranteed-financial-return claim' },
  { re: /your faith (unlocks|guarantees|releases|activates) (wealth|money|riches|abundance|prosperity)/i, label: 'faith-as-wealth-formula' },
  { re: /(plant|give) (your )?(seed|gift) (and|to) (receive|unlock|get|reap)/i, label: 'transactional seed-to-yield' }
];
const T1_WARN = [
  { re: /\bself[\s-]?made\b/i, label: 'self-made framing (source-of-power drift)' },
  { re: /get rich|guaranteed riches/i, label: 'yield-as-goal language' }
];

// ---- Test 2: John 10:10 -- abundant life, not the thief.
const T2_BLOCK = [
  { re: /sell(ing)? (your |user |family |their |member )?data/i, label: 'selling user/family data' },
  { re: /data[\s-]?broker/i, label: 'data-broker model' },
  { re: /(advertis|ad)[\s-]?(model|revenue|driven)|sell ads|ad network/i, label: 'advertising-revenue model' },
  { re: /engagement[\s-]?(optimiz|maximiz)|optimize for engagement|maximize (daily )?(active users|time[\s-]?on[\s-]?app|screen[\s-]?time)/i, label: 'engagement-maximization' },
  { re: /dark pattern|infinite scroll|addictive|hook the user/i, label: 'dark-pattern / addiction design' },
  { re: /data[\s-]?lock[\s-]?in|cannot export|no export|trap (the |our )?user/i, label: 'data lock-in' },
  { re: /surveil|track (the |our |every )?(user|family|congregation|member)s?\b/i, label: 'surveillance framing' },
  { re: /sell (anonymized |aggregated )?(user|family|member) (data|information)/i, label: 'selling member data' }
];
const T2_WARN = [
  { re: /monetiz/i, label: 'monetization language (verify it is not extraction)' }
];

// ---- Test 3: James 1:27 -- care for the afflicted AND unstained from the world.
const T3_BLOCK = [
  { re: /(for|serves?) (the )?(white|one) (race|people|families|congregation)s? (only|alone)/i, label: 'race-exclusive "church" counterfeit' },
  { re: /separation of the races|racial (purity|separation)|god ordained .{0,24}(races|segregation|separation)/i, label: 'ordained-racial-separation claim' },
  { re: /our (race|kind|kin|people) (only|alone|first)\b/i, label: 'race-supremacy framing' },
  { re: /whites?[\s-]?only|no (blacks?|minorities|immigrants|jews?)\b/i, label: 'racial exclusion' },
  { re: /(exclude|deny|turn away|cast out) (the )?(poor|needy|widows?|orphans?|elderly|disabled|underserved|afflicted)/i, label: 'exclusion of the vulnerable' }
];
const T3_WARN = [
  { re: /exclusive (access|tier|club|membership)/i, label: 'exclusivity language (verify it is hospitality, not gatekeeping)' }
];

// ---- Test 4: Grace and Mercy Standard -- no precision-gatekeeping, no
// grace-withdrawal, no declaring users outside fellowship.
const T4_BLOCK = [
  { re: /must (believe|affirm|accept|confess) [^.]{0,48}(to (access|use|join|be welcome|continue|enter))/i, label: 'theological-precision gatekeeping' },
  { re: /(lose|revoke|withdraw)s? (their )?(access|grace|welcome|fellowship)[^.]{0,36}(if|when|after|once)[^.]{0,36}(sin|relapse|fail|fall|doubt|backslide)/i, label: 'grace-withdrawal-on-behavior' },
  { re: /(declared?|placed?|put) outside (of )?(the )?(fellowship|faith|body|church)\b/i, label: 'declaring-users-outside-fellowship' },
  { re: /second[\s-]?chance tier|probation(ary)? (mode|tier|account|status)/i, label: 'probationary/second-chance gating' },
  { re: /no longer (welcome|saved|in fellowship|one of us)/i, label: 'withdrawal-of-welcome' },
  { re: /only (real|true) (christians|believers) (may|can|are allowed|deserve)/i, label: 'precision-gatekeeping' }
];
const T4_WARN = [
  { re: /you (are|will be) (condemned|damned|cast out)/i, label: 'condemnation tone (Scripture-as-club risk)' }
];

// ---- Deterministic typographic-theology guard (CLAUDE.md, Layer 0). Feeds
// Test 3 (unstained). Adversary names matched here are violation targets.
const adversaryCapRe = /\b(Lucifer|Satan|Devil|Dragon|Accuser|Deceiver)\b/; // case-sensitive on purpose
const godLowerRe = /\b(yahweh|jesus christ|holy spirit)\b/; // lowercase-only on purpose
const typoExtraBlock = [];
if (adversaryCapRe.test(content)) {
  typoExtraBlock.push('adversary name capitalized (CLAUDE.md typographic theology)');
}
const faithSurface = /(church|spiritual|faith|scripture|gospel|worship|sermon|congregation|body of christ|tithe|godhead|testimony)/i
  .test(surfaceType + ' ' + content);
const typoExtraWarn = [];
if (faithSurface && godLowerRe.test(content)) {
  typoExtraWarn.push('God-name not capitalized in faith content (CLAUDE.md typographic theology)');
}

function evalTest(key, name, anchorRef, anchorText, blockPats, warnPats, extraBlock, extraWarn) {
  const blockHits = anyMatch(content, blockPats).concat(extraBlock || []);
  const warnHits = anyMatch(content, warnPats).concat(extraWarn || []);
  let verdict = 'pass';
  let signals = [];
  if (blockHits.length) { verdict = 'block'; signals = blockHits; }
  else if (warnHits.length) { verdict = 'warn'; signals = warnHits; }
  return { key: key, name: name, verdict: verdict, signals: signals, scripture_anchor: { ref: anchorRef, text: anchorText } };
}

const t1 = evalTest(
  'deut_8_18', 'Yahweh-source (not a wealth formula)',
  'Deuteronomy 8:18',
  'You shall remember the LORD your God, for it is he who gives you power to get wealth, that he may confirm his covenant that he swore to your fathers, as it is this day.',
  T1_BLOCK, T1_WARN);
const t2 = evalTest(
  'john_10_10', 'Abundant life, not the thief (no extraction)',
  'John 10:10',
  'The thief comes only to steal and kill and destroy. I came that they may have life and have it abundantly.',
  T2_BLOCK, T2_WARN);
const t3 = evalTest(
  'james_1_27', 'Care for the afflicted and unstained from the world',
  'James 1:27',
  'Religion that is pure and undefiled before God the Father is this: to visit orphans and widows in their affliction, and to keep oneself unstained from the world.',
  T3_BLOCK, T3_WARN, typoExtraBlock, typoExtraWarn);
const t4 = evalTest(
  'grace_and_mercy', 'Grace and Mercy Standard (no gatekeeping, no grace-withdrawal)',
  'Romans 5:8',
  'But God shows his love for us in that while we were still sinners, Christ died for us.',
  T4_BLOCK, T4_WARN);

const tests = [t1, t2, t3, t4];
const failing = tests.filter(function (t) { return t.verdict === 'block'; });
const warning = tests.filter(function (t) { return t.verdict === 'warn'; });
const decision = failing.length ? 'BLOCK' : (warning.length ? 'WARN' : 'PASS');

let reasoning;
let scriptureAnchor;
if (decision === 'BLOCK') {
  reasoning = failing.map(function (t) { return t.name + ' -> ' + t.signals.join('; '); }).join(' | ');
  scriptureAnchor = failing[0].scripture_anchor;
} else if (decision === 'WARN') {
  reasoning = warning.map(function (t) { return t.name + ' -> ' + t.signals.join('; '); }).join(' | ');
  scriptureAnchor = warning[0].scripture_anchor;
} else {
  reasoning = 'All four ethical tests pass. The surface honors Yahweh as source (Deut 8:18), brings abundant life rather than extraction (John 10:10), cares for the afflicted while staying unstained (James 1:27), and preserves grace (Romans 5:8).';
  scriptureAnchor = { ref: 'Proverbs 4:7', text: 'Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.' };
}

// ---- Dust-off-feet tally (Section O / Matthew 10:14). Count prior BLOCKs for
// this surface_id; a surface that keeps failing escalates to human governance.
const QG_DIR = '/data/chatin/_telemetry/qg';
try { fs.mkdirSync(QG_DIR, { recursive: true }); } catch (e) { /* dir exists */ }
const eventsPath = path.join(QG_DIR, '_events.jsonl');

let priorBlocks = 0;
try {
  const raw = fs.readFileSync(eventsPath, 'utf8');
  const lines = raw.split('\n');
  for (let i = 0; i < lines.length; i++) {
    if (!lines[i]) continue;
    let e = null;
    try { e = JSON.parse(lines[i]); } catch (_) { e = null; }
    if (e && e.surface_id === surfaceId && e.decision === 'BLOCK') priorBlocks++;
  }
} catch (e) { /* no events file yet */ }

const DUST_THRESHOLD = 3;
const blockCountIncludingNow = priorBlocks + (decision === 'BLOCK' ? 1 : 0);
const dustOffFeet = decision === 'BLOCK' && blockCountIncludingNow >= DUST_THRESHOLD;

const ts = new Date().toISOString();
const safeTs = ts.replace(/[:.]/g, '-');

const record = {
  ok: true,
  decision: decision,
  surface_type: surfaceType,
  surface_id: surfaceId,
  tests: tests,
  reasoning: reasoning,
  scripture_anchor: scriptureAnchor,
  dust_off_feet: dustOffFeet,
  repeat_block_count: blockCountIncludingNow,
  overridable: true,
  override_authority: ['Darrell Poe', 'Christina Poe', 'Bishop Gwin'],
  override_note: 'wf36 is advisory, not absolute. An authorized governor may override a BLOCK by logging the override per QUALITY-GATEKEEPER.md.',
  metadata: { commit_hash: commitHash, author: author, sovereign_mesh_tier: sovereignMeshTier },
  ts: ts
};

let loggedTo = null;
try {
  const f = path.join(QG_DIR, safeTs + '__gate.json');
  fs.writeFileSync(f, JSON.stringify(record, null, 2));
  loggedTo = f;
} catch (e) { record.log_error = e.message; }

try {
  fs.appendFileSync(eventsPath, JSON.stringify({ ts: ts, surface_id: surfaceId, surface_type: surfaceType, decision: decision, commit_hash: commitHash }) + '\n');
} catch (e) { /* non-fatal */ }

record.logged_to = loggedTo;

// ---- Synology Chat alert text (used only on BLOCK).
const chatLines = [];
chatLines.push('BLOCK -- Quality Gatekeeper (wf36)');
chatLines.push('surface: ' + surfaceType + (surfaceId !== surfaceType ? ' [' + surfaceId + ']' : ''));
if (commitHash) chatLines.push('commit: ' + commitHash.slice(0, 12) + (author ? ' by ' + author : ''));
chatLines.push('failed: ' + failing.map(function (t) { return t.name; }).join(', '));
chatLines.push('why: ' + reasoning);
chatLines.push('anchor: ' + scriptureAnchor.ref + ' -- ' + scriptureAnchor.text);
if (dustOffFeet) {
  chatLines.push('DUST-OFF-FEET: this surface has hit BLOCK ' + blockCountIncludingNow + ' times. Escalate to human governance (Darrell + Christina + Bishop Gwin).');
}
chatLines.push('advisory: a governor may override and log per QUALITY-GATEKEEPER.md.');
record.chat_text = chatLines.join('\n');
record.should_alert = (decision === 'BLOCK');

return [{ json: record }];
